css:
.card {
  width: 290px;
  height: 404px;
  background: linear-gradient(10deg, rgb(212, 38, 255) 0%, rgb(76, 0, 255) 100%);
  border-radius: 16px;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(10.5px);
  -webkit-backdrop-filter: blur(10.5px);
  border: 1px solid rgba(255, 255, 255, 0.3);
}

.top {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 16px;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(10.5px);
  -webkit-backdrop-filter: blur(10.5px);
  border: 1px solid rgba(255, 255, 255, 0.3);
  width: 290px;
  height: 300px;
}

.top .title {
  color: #fff;
  font-weight: bolder;
  font-size: x-large;
  margin-left: 10px;
  margin-top: 90%
}

.card .desc {
  color: #fff;
  opacity: 75%;
  font-size: small;
  font-weight: lighter;
  margin-left: 10px;
  margin-top: 2%
}
